## solutions

#### depth first recursive

```cpp
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <string>

std::unordered_map<int, std::vector<int>> buildGraph(int n, std::vector<std::vector<int>> edges) {
  std::unordered_map<int, std::vector<int>> graph;
  for (int i = 0; i < n; i += 1) {
    graph[i] = std::vector<int>();
  }

  for (std::vector<int> edge : edges) {
    int a = edge[0];
    int b = edge[1];
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  return graph;
}

bool validate(std::unordered_map<int, std::vector<int>> graph, std::unordered_set<int> &visited, int node, int lastNode) {
  if (visited.count(node) > 0) {
    return false;
  }

  visited.insert(node);

  for (int neighbor : graph[node]) {
    if (neighbor != lastNode && !validate(graph, visited, neighbor, node)) {
      return false; 
    }
  }

  return true;
}

bool rareRouting(int n, std::vector<std::vector<int>> roads) {
  std::unordered_map<int, std::vector<int>> graph = buildGraph(n, roads);
  std::unordered_set<int> visited;
  bool valid = validate(graph, visited, 0, -1);
  return valid && visited.size() == n;
}
```

- n = number of nodes
- Time: O(n^2)
- Space: O(n)
